B.auk=new A.fg("Contrast the return with the opening and show the cost of change.","\u0421\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0441 \u043d\u0430\u0447\u0430\u043b\u043e\u043c \u0438 \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u0446\u0435\u043d\u0443 \u043f\u0435\u0440\u0435\u043c\u0435\u043d.","scene","return","Return with a difference","\u0412\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0441 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043e\u0439")
B.au7=new A.fg("Plan a self-contained desire, obstacle, choice and consequence.","\u041d\u0430\u043c\u0435\u0442\u044c\u0442\u0435 \u0441\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0438\u0441\u0442\u043e\u0440\u0438\u044e: \u0436\u0435\u043b\u0430\u043d\u0438\u0435, \u043f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0438\u0435, \u0432\u044b\u0431\u043e\u0440 \u0438 \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435.","scene","story","Story","\u0420\u0430\u0441\u0441\u043a\u0430\u0437")
B.atV=new A.fg("Identify a specific reader situation and a testable promise.","\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u0435 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044e \u0447\u0438\u0442\u0430\u0442\u0435\u043b\u044f \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u043e\u0435 \u043e\u0431\u0435\u0449\u0430\u043d\u0438\u0435 \u043a\u043d\u0438\u0433\u0438.","context","problem","The reader's problem","\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u0430 \u0447\u0438\u0442\u0430\u0442\u0435\u043b\u044f")
B.aun=new A.fg("Define only the concepts needed for the next argument.","\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u0435 \u043f\u043e\u043d\u044f\u0442\u0438\u044f, \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u0435 \u0434\u043b\u044f \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044f.","terms","concept","Key concepts","\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u043e\u043d\u044f\u0442\u0438\u044f")
B.au9=new A.fg("Explain the background without substituting chronology for causation.","\u041e\u0431\u044a\u044f\u0441\u043d\u0438\u0442\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u0441\u044b\u043b\u043a\u0438, \u043d\u0435 \u043f\u043e\u0434\u043c\u0435\u043d\u044f\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u043d\u043e\u0441\u0442\u044c \u0445\u0440\u043e\u043d\u043e\u043b\u043e\u0433\u0438\u0435\u0439.","context","context","How we got here","\u041a\u0430\u043a \u043c\u044b \u043a \u044d\u0442\u043e\u043c\u0443 \u043f\u0440\u0438\u0448\u043b\u0438")
B.atW=new A.fg("Specify prerequisites, procedure and a way to check the result.","\u0423\u043a\u0430\u0436\u0438\u0442\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f, \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0443 \u0438 \u0441\u043f\u043e\u0441\u043e\u0431 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430.","method","method","The method and its conditions","\u041c\u0435\u0442\u043e\u0434 \u0438 \u0435\u0433\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f")
B.au2=new A.fg("Build a sequence of actions with inputs and completion criteria.","\u041f\u043e\u0441\u0442\u0440\u043e\u0439\u0442\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0441 \u0432\u0445\u043e\u0434\u043d\u044b\u043c\u0438 \u0434\u0430\u043d\u043d\u044b\u043c\u0438 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f\u043c\u0438 \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u0438.","steps","process","From intention to action","\u041e\u0442 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u044f \u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044e")
B.au3=new A.fg("Collect a real case and separate observed results from your interpretation.","\u0421\u043e\u0431\u0435\u0440\u0438\u0442\u0435 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u0435\u0439\u0441 \u0438 \u043e\u0442\u0434\u0435\u043b\u0438\u0442\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043e\u0442 \u0442\u0440\u0430\u043a\u0442\u043e\u0432\u043a\u0438.","example","case","A case examined closely","\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u044b\u0439 \u0440\u0430\u0437\u0431\u043e\u0440 \u0441\u043b\u0443\u0447\u0430\u044f")
B.aub=new A.fg("Create a task the reader can complete and evaluate independently.","\u041f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u044c\u0442\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0435, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0447\u0438\u0442\u0430\u0442\u0435\u043b\u044c \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442 \u0441\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u043e.","checklist","exercise","Practice and self-check","\u041f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u0438 \u0441\u0430\u043c\u043e\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430")
B.auo=new A.fg("State the claim, supporting reasons and the strongest objection.","\u0421\u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0439\u0442\u0435 \u0442\u0435\u0437\u0438\u0441, \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u044f \u0438 \u0441\u0438\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0435 \u0432\u043e\u0437\u0440\u0430\u0436\u0435\u043d\u0438\u0435.","thesis","argument","The central argument","\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442")
B.aul=new A.fg("Connect every significant claim to material that can be verified.","\u0421\u0432\u044f\u0436\u0438\u0442\u0435 \u043a\u0430\u0436\u0434\u043e\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u0441 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u043c \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u043c.","evidence","evidence","Evidence and sources","\u0414\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438")
